"""Generated by the loop's null stub. No edge by construction.

Momentum on the last closed bar of a 5m series, bracketed at
1.7223/0.55. On the synthetic generator's pure-noise sessions there is
nothing for this to find, whatever the parameters, which is exactly why it is
what the correction is calibrated against.
"""

from __future__ import annotations


class Strategy:
    def setup(self, ctx) -> None:
        ctx.subscribe("5m")

    def on_bars(self, ctx) -> None:
        if ctx.position or ctx.working_order_ids:
            return
        history = ctx.history("5m")
        if len(history) < 2:
            return
        last = history[-1]
        if last.close == last.open:
            return
        rising = last.close > last.open
        place = ctx.buy if rising is True else ctx.sell
        place(size=1, stop_offset=1.7223, target_offset=0.55, tag="entry")

    def on_fill(self, ctx) -> None:
        pass

    def on_lifecycle(self, ctx) -> None:
        pass
